CREATE TABLE `cosorder` (
  `id` bigint(20) NOT NULL,
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `order_no` varchar(64) DEFAULT NULL COMMENT '订单号',
  `user_id` bigint(20) DEFAULT NULL COMMENT '用户ID',
  `user_table` varchar(100) DEFAULT NULL COMMENT '用户表',
  `total_amount` decimal(10,2) DEFAULT NULL COMMENT '订单总额',
  `pay_status` varchar(50) DEFAULT '未支付' COMMENT '支付状态',
  `order_status` varchar(50) DEFAULT '待确认' COMMENT '订单状态',
  `pay_type` varchar(100) DEFAULT NULL COMMENT '支付方式',
  `pay_order_no` varchar(64) DEFAULT NULL COMMENT '支付单号',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `pay_channel_trade_no` varchar(100) DEFAULT NULL COMMENT '三方交易号',
  `contact_name` varchar(100) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(100) DEFAULT NULL COMMENT '联系电话',
  `address` varchar(255) DEFAULT NULL COMMENT '地址',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `items_json` longtext COMMENT '订单商品快照JSON',
  `designer_id` bigint(20) DEFAULT NULL COMMENT '认领设计师ID',
  `designer_table` varchar(100) DEFAULT NULL COMMENT '设计师表名',
  `designer_status` varchar(50) DEFAULT '待接单' COMMENT '设计师接单状态',
  `designer_take_time` datetime DEFAULT NULL COMMENT '认领时间',
  `address_snapshot_json` longtext COMMENT '地址快照JSON',
  `body_profile_snapshot_json` longtext COMMENT '身材快照JSON',
  `address_id` bigint(20) DEFAULT NULL COMMENT '地址簿ID',
  `body_profile_id` bigint(20) DEFAULT NULL COMMENT '身材档案ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cosorder_order_no` (`order_no`),
  KEY `idx_cosorder_user` (`user_id`),
  KEY `idx_cosorder_no` (`order_no`),
  KEY `idx_cosorder_pay_status` (`pay_status`),
  KEY `idx_cosorder_order_status` (`order_status`),
  KEY `idx_cosorder_addtime` (`addtime`),
  KEY `idx_cosorder_address_id` (`address_id`),
  KEY `idx_cosorder_body_profile_id` (`body_profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='COS订单';
